// --- SABİT HARİTALAR VE VERİTABANLARI ---

const yaskaSectorMapping = {
  "Sağlık Sektörü": {
    english_keywords_general_poi: ["Health & Medical"],
    german_keywords_specific_poi: ["arzt", "ärzte", "klinik", "apotheke", "heilpraktiker", "alternativmediziner", "physiotherapeut", "zahnarzt", "medizin", "gesundheit"],
    yaska_category_group_tr: "Sağlık Sektörü", yaska_category_group_en: "Healthcare Sector", yaska_category_group_de: "Gesundheitssektor"
  },
  "Otomotiv Sektörü": {
    english_keywords_general_poi: ["Automotive", "Automotive / Shopping", "Transportation"],
    german_keywords_specific_poi: ["autohändler", "autowerkstatt", "kfz", "autoteile", "fahrzeug", "reifen", "auto", "werkstatt"],
    yaska_category_group_tr: "Otomotiv Sektörü", yaska_category_group_en: "Automotive Sector", yaska_category_group_de: "Automobilsektor"
  },
  "Hukuk Sektörü": {
    english_keywords_general_poi: ["Professional Services", "Legal"],
    german_keywords_specific_poi: ["anwalt", "rechtsanwalt", "kanzlei", "notar", "jurist", "recht"],
    yaska_category_group_tr: "Hukuk Sektörü", yaska_category_group_en: "Legal Sector", yaska_category_group_de: "Rechtssektor"
  },
  "Zanaatkar/Usta Sektörü": {
    english_keywords_general_poi: ["Construction & Home Improvement", "Services", "Craftsmanship", "Trades"],
    german_keywords_specific_poi: ["handwerker", "meisterbetrieb", "tischler", "maler", "elektriker", "installateur", "dachdecker", "schreiner", "heizung", "sanitär", "bau", "raumausstatter"],
    yaska_category_group_tr: "Zanaatkar/Usta Sektörü", yaska_category_group_en: "Craftsmen/Trades Sector", yaska_category_group_de: "Handwerkssektor"
  },
  "Emlak Sektörü": {
    english_keywords_general_poi: ["Real Estate", "Property"],
    german_keywords_specific_poi: ["immobilien", "makler", "wohnung", "hausverwaltung", "grundstück", "vermietung"],
    yaska_category_group_tr: "Emlak Sektörü", yaska_category_group_en: "Real Estate Sector", yaska_category_group_de: "Immobiliensektor"
  },
  "Güzellik Sektörü": {
    english_keywords_general_poi: ["Personal Care & Beauty", "Health & Wellness", "Salon"],
    german_keywords_specific_poi: ["schönheitssalon", "kosmetikstudio", "friseur", "nagelstudio", "wellness", "beauty", "kosmetik", "haare"],
    yaska_category_group_tr: "Güzellik Sektörü", yaska_category_group_en: "Beauty Sector", yaska_category_group_de: "Schönheitssektor"
  },
  "Eğitim Sektörü": {
    english_keywords_general_poi: ["Education", "Education & Culture"],
    german_keywords_specific_poi: ["schule", "universität", "kurs", "nachhilfe", "bildungszentrum", "fahrschule", "bildung", "unterricht", "kindertagesstätte", "kita"],
    yaska_category_group_tr: "Eğitim Sektörü", yaska_category_group_en: "Education Sector", yaska_category_group_de: "Bildungssektor"
  },
  "Genel Hizmet Sektörü": {
    english_keywords_general_poi: ["Food & Drink", "Accommodation", "Services (General)", "Arts & Entertainment", "Tourism", "Shopping", "Retail", "Business Services", "Financial Services", "Professional Services", "Legal"],
    german_keywords_specific_poi: ["restaurant", "hotel", "dienstleistung", "gastronomie", "berater", "agentur", "versicherung", "bank", "geschäft", "laden", "tourismus", "unterhaltung", "steuerberater"],
    yaska_category_group_tr: "Genel Hizmet Sektörü", yaska_category_group_en: "General Services Sector", yaska_category_group_de: "Allgemeiner Dienstleistungssektor"
  },
  "Diğer/Bilinmeyen": {
    english_keywords_general_poi: [], german_keywords_specific_poi: [],
    yaska_category_group_tr: "Diğer/Bilinmeyen", yaska_category_group_en: "Other/Unknown", yaska_category_group_de: "Sonstige/Unbekannt"
  }
};

const generalCategoryTranslations = {
  "Health & Medical": { german: "Gesundheit & Medizin", turkish: "Sağlık & Tıp" },
  "Automotive / Shopping": { german: "Automobil / Einkaufen", turkish: "Otomotiv / Alışveriş" },
  "Automotive": { german: "Automobil", turkish: "Otomotiv" },
  "Transportation": { german: "Transport", turkish: "Ulaşım" },
  "Professional Services": { german: "Professionelle Dienstleistungen", turkish: "Profesyonel Hizmetler" },
  "Legal": { german: "Recht", turkish: "Hukuk" },
  "Industry & Manufacturing": { german: "Industrie & Herstellung", turkish: "Sanayi & Üretim" },
  "Financial Services": { german: "Finanzdienstleistungen", turkish: "Finansal Hizmetler" },
  "Business Services": { german: "Geschäftsdienstleistungen", turkish: "İş Hizmetleri" },
  "Food & Drink": { german: "Essen & Trinken", turkish: "Yeme & İçme" },
  "Construction & Home Improvement": { german: "Bau & Heimwerken", turkish: "İnşaat & Ev Geliştirme" },
  "Services": { german: "Dienstleistungen", turkish: "Hizmetler" },
  "Craftsmanship": { german: "Handwerk", turkish: "Zanaatkarlık" },
  "Trades": { german: "Gewerbe", turkish: "Meslekler/Esnaf" },
  "Real Estate": { german: "Immobilien", turkish: "Emlak" },
  "Property": { german: "Eigentum", turkish: "Mülk" },
  "Personal Care & Beauty": { german: "Körperpflege & Schönheit", turkish: "Kişisel Bakım & Güzellik" },
  "Health & Wellness": { german: "Gesundheit & Wellness", turkish: "Sağlık & Zindelik" },
  "Salon": { german: "Salon", turkish: "Salon" },
  "Education": { german: "Bildung", turkish: "Eğitim" },
  "Education & Culture": { german: "Bildung & Kultur", turkish: "Eğitim & Kültür" },
  "Accommodation": { german: "Unterkunft", turkish: "Konaklama" },
  "Services (General)": { german: "Allgemeine Dienstleistungen", turkish: "Genel Hizmetler" },
  "Arts & Entertainment": { german: "Kunst & Unterhaltung", turkish: "Sanat & Eğlence" },
  "Tourism": { german: "Tourismus", turkish: "Turizm" },
  "Shopping": { german: "Einkaufen", turkish: "Alışveriş" },
  "Retail": { german: "Einzelhandel", turkish: "Perakende" },
  "Uncategorized": { german: "Unkategorisiert", turkish: "Kategorize Edilmemiş" },
  "Error/Unknown": { german: "Fehler/Unbekannt", turkish: "Hata/Bilinmiyor" }
};

const detailedPoiToGeneralEnglishPoi = [
  { german_detailed: "kindertagesstätte", general_english_poi_category: "Education" },
  { german_detailed: "kita", general_english_poi_category: "Education" },
  { german_detailed: "arzt", general_english_poi_category: "Health & Medical" },
  { german_detailed: "ärzte", general_english_poi_category: "Health & Medical" },
  { german_detailed: "klinik", general_english_poi_category: "Health & Medical" },
  { german_detailed: "apotheke", general_english_poi_category: "Health & Medical" },
  { german_detailed: "autohändler", general_english_poi_category: "Automotive / Shopping" },
  { german_detailed: "autowerkstatt", general_english_poi_category: "Automotive" },
  { german_detailed: "maschinenbau", general_english_poi_category: "Industry & Manufacturing" },
  { german_detailed: "pizzeria", general_english_poi_category: "Food & Drink" },
  { german_detailed: "rechtsanwalt", general_english_poi_category: "Legal" },
  { german_detailed: "notar", general_english_poi_category: "Legal" },
  { german_detailed: "tischler", general_english_poi_category: "Craftsmanship" },
  { german_detailed: "maler", general_english_poi_category: "Craftsmanship" },
  { german_detailed: "immobilienmakler", general_english_poi_category: "Real Estate" },
  { german_detailed: "friseur", general_english_poi_category: "Salon" },
  { german_detailed: "kosmetikstudio", general_english_poi_category: "Personal Care & Beauty" },
  { german_detailed: "schule", general_english_poi_category: "Education" },
  { german_detailed: "restaurant", general_english_poi_category: "Food & Drink" },
  { german_detailed: "hotel", general_english_poi_category: "Accommodation" },
];

// --- ANA İŞLEM MANTIĞI ---

const items = $input.all();
const results = [];

for (const item of items) {
  const leadData = item.json;

  // 1. KATEGORİ ADINI TEMİZLE VE DÜZELT
  let originalGermanCategory = leadData.category ? leadData.category.trim() : "";
  try {
    // Bozuk UTF-8 karakterlerini ("Ã¤" -> "ä") düzelt
    const decoded = Buffer.from(originalGermanCategory, 'latin1').toString('utf8');
    // Eğer '�' (geçersiz karakter) içermiyorsa, düzeltilmiş halini kullan
    if (!decoded.includes('�')) {
        originalGermanCategory = decoded;
    }
  } catch (e) {
    // Hata olursa görmezden gel, orijinal değeri kullan
  }
  const cleanedCategory = originalGermanCategory.toLowerCase();

  // 2. KATEGORİZASYON DEĞİŞKENLERİNİ TANIMLA
  let determinedYaskaSector = null;
  let general_poi_details = null;
  let needs_llm_lookup = true; // Varsayılan: LLM'e git

  // 3. KURAL TABANLI EŞLEŞTİRME (HIZLI YOL)
  // Adım 3a: Detaylı POI listesini kontrol et
  const matchedDetailedPoi = detailedPoiToGeneralEnglishPoi.find(
    entry => cleanedCategory.includes(entry.german_detailed)
  );

  if (matchedDetailedPoi) {
    const generalEngCategory = matchedDetailedPoi.general_english_poi_category;
    if (generalCategoryTranslations[generalEngCategory]) {
      general_poi_details = {
        original_german_category: originalGermanCategory,
        mapped_poi_category_german: generalCategoryTranslations[generalEngCategory].german,
        mapped_poi_category_english: generalEngCategory,
        mapped_poi_category_turkish: generalCategoryTranslations[generalEngCategory].turkish
      };
      // Bu genel POI ile bir Yaska sektörü bulabilir miyiz?
      for (const sectorName in yaskaSectorMapping) {
        const sectorData = yaskaSectorMapping[sectorName];
        if (sectorData.english_keywords_general_poi.includes(generalEngCategory)) {
          determinedYaskaSector = {
            yaska_tr: sectorData.yaska_category_group_tr,
            yaska_en: sectorData.yaska_category_group_en,
            yaska_de: sectorData.yaska_category_group_de,
            match_type: "yaska_from_detailed_poi"
          };
          break; // Sektör bulundu, döngüden çık
        }
      }
      needs_llm_lookup = false; // Detaylı eşleşme bulundu, LLM'e gerek yok
    }
  }

  // Adım 3b: Eğer hala sektör bulunamadıysa, Yaska'nın kendi anahtar kelimelerini kontrol et
  if (!determinedYaskaSector) {
    for (const sectorName in yaskaSectorMapping) {
      const sectorData = yaskaSectorMapping[sectorName];
      if (sectorData.german_keywords_specific_poi.some(keyword => cleanedCategory.includes(keyword))) {
        determinedYaskaSector = {
          yaska_tr: sectorData.yaska_category_group_tr,
          yaska_en: sectorData.yaska_category_group_en,
          yaska_de: sectorData.yaska_category_group_de,
          match_type: "yaska_specific_keyword"
        };
        // POI detayını da varsayılan olarak ata
        const matchedGeneralPoiEng = sectorData.english_keywords_general_poi[0] || "Uncategorized";
        if (generalCategoryTranslations[matchedGeneralPoiEng] && !general_poi_details) {
            general_poi_details = {
                original_german_category: originalGermanCategory,
                mapped_poi_category_german: generalCategoryTranslations[matchedGeneralPoiEng].german,
                mapped_poi_category_english: matchedGeneralPoiEng,
                mapped_poi_category_turkish: generalCategoryTranslations[matchedGeneralPoiEng].turkish
            };
        }
        needs_llm_lookup = false; // Yaska anahtar kelimesiyle eşleşti, LLM'e gerek yok
        break;
      }
    }
  }

  // 4. FALLBACK (Eğer hiçbir kural eşleşmediyse)
  if (!determinedYaskaSector) {
    determinedYaskaSector = {
      ...yaskaSectorMapping["Diğer/Bilinmeyen"],
      match_type: "fallback_needs_llm"
    };
    needs_llm_lookup = true; // Hiçbir kural çalışmadı, LLM'e kesin git
  }

  // 5. SONUCU OLUŞTUR
  results.push({
    json: {
      ...leadData, // Orijinal lead verisini olduğu gibi taşı
      categorization_attempt: { // Tüm yeni bilgileri bu nesne altına topla
          yaska_sector_info: determinedYaskaSector,
          general_poi_info_from_db: general_poi_details,
          needs_llm_lookup: needs_llm_lookup,
          original_german_category_for_processing: originalGermanCategory
      }
    }
  });
}

return results;

// --- SABİT SYSTEM PROMPT (Genel POI Sınıflandırması için) ---
const system_prompt_content = `Sen, coğrafi konum verileri ve İlgi Çekici Noktalar (POI) konusunda uzman bir yapay zeka asistanısın.
Görevin, kullanıcı tarafından sağlanan Almanca bir POI (Point of Interest) kategori adını analiz etmek ve bazen önceden tahmin edilmiş bir İngilizce genel POI kategorisini de dikkate alarak, bu Almanca kategori için en uygun standart İngilizce genel POI kategorisini belirlemek ve bu belirlediğin İngilizce genel POI kategorisinin Almanca ve Türkçe karşılıklarını sağlamaktır.
Sağlanan Ana İngilizce Genel POI Kategorileri (bunları veya çok yakınlarını kullanmaya çalış):
[
"Health & Medical", "Automotive", "Automotive / Shopping", "Transportation", "Professional Services", "Legal",
"Industry & Manufacturing", "Financial Services", "Business Services", "Food & Drink",
"Construction & Home Improvement", "Services", "Craftsmanship", "Trades", "Real Estate", "Property",
"Personal Care & Beauty", "Health & Wellness", "Salon", "Education", "Education & Culture",
"Accommodation", "Services (General)", "Arts & Entertainment", "Tourism", "Shopping", "Retail",
"Uncategorized", "Other"
]
Çıktıyı daima aşağıdaki JSON formatında ver:
{
"original_german_category": "GİRDİ OLARAK VERİLEN ALMANCA KATEGORİ ADI",
"refined_english_general_poi": "SENİN BELİRLEDİĞİN STANDART İNGİLİZCE GENEL POI KATEGORİSİ",
"mapped_poi_category_german": "BELİRLEDİĞİN İNGİLİZCE GENEL POI KATEGORİSİNİN ALMANCA KARŞILIĞI",
"mapped_poi_category_turkish": "BELİRLEDİĞİN İNGİLİZCE GENEL POI KATEGORİSİNİN TÜRKÇE KARŞILIĞI"
}
Örnek 1 (Ön Bilgi Yok):
Kullanıcı Girdisi: Almanca Kategori: "Maschinenbau"
Senin Çıktın:
{
"original_german_category": "Maschinenbau",
"refined_english_general_poi": "Industry & Manufacturing",
"mapped_poi_category_german": "Industrie & Herstellung",
"mapped_poi_category_turkish": "Sanayi & Üretim"
}
Örnek 2 (Ön Bilgi Var):
Kullanıcı Girdisi: Almanca Kategori: "Arztpraxis", Önerilen İngilizce Genel POI: "Services"
Senin Çıktın (Düzeltilmiş/Onaylanmış):
{
"original_german_category": "Arztpraxis",
"refined_english_general_poi": "Health & Medical",
"mapped_poi_category_german": "Gesundheit & Medizin",
"mapped_poi_category_turkish": "Sağlık & Tıp"
}
Örnek 3 (Ön Bilgi Var ve Doğru):
Kullanıcı Girdisi: Almanca Kategori: "Pizzeria", Önerilen İngilizce Genel POI: "Food & Drink"
Senin Çıktın:
{
"original_german_category": "Pizzeria",
"refined_english_general_poi": "Food & Drink",
"mapped_poi_category_german": "Essen & Trinken",
"mapped_poi_category_turkish": "Yeme & İçme"
}
`;

// --- ANA İŞLEM MANTIĞI ---
const items = $input.all();
const results = [];

for (const item of items) {
  // Bu düğüme gelen tüm veriyi al (id, name, categorization_attempt vs. içerir)
  const leadWithCategorizationAttempt = item.json;

  // Gerekli bilgileri yeni 'categorization_attempt' nesnesinden al
  const categorizationInfo = leadWithCategorizationAttempt.categorization_attempt;
  const germanCategoryForLlm = categorizationInfo.original_german_category_for_processing;

  if (!germanCategoryForLlm) {
    // LLM işlemi bu lead için atlanıyor, ama veriyi yine de koruyarak ilerleyebiliriz
    results.push({
      json: {
        ...leadWithCategorizationAttempt, // Orijinal veriyi koru
        llm_error_message: "LLM için Almanca kategori adı bulunamadı."
      }
    });
    continue;
  }

  // Kullanıcı komutunu (User Prompt) oluştur
  let user_prompt_content = `Almanca POI Kategori Adı: "${germanCategoryForLlm}".\n`;

  // Eğer kural tabanlı bir tahmin varsa, bunu komuta ekle
  const suggestedPoi = categorizationInfo.general_poi_info_from_db;
  if (suggestedPoi && suggestedPoi.mapped_poi_category_english) {
    user_prompt_content += `Veritabanı tabanlı önerilen İngilizce Genel POI Kategorisi: "${suggestedPoi.mapped_poi_category_english}".\nBu öneriyi de dikkate alarak veya düzelterek en uygun standart İngilizce genel POI kategorisini ve onun Almanca/Türkçe çevirilerini belirle.`;
  } else {
    user_prompt_content += `Bu Almanca kategori için en uygun standart İngilizce genel POI kategorisini ve onun Almanca/Türkçe çevirilerini belirle.`;
  }

  // LLM'e gönderilecek nihai mesaj yapısını oluştur
  const messagesForLlm = [
    { "role": "system", "content": system_prompt_content },
    { "role": "user", "content": user_prompt_content }
  ];

  results.push({
    json: {
      // *** EN ÖNEMLİ KISIM: VERİ TAŞIMA ***
      // Orijinal lead verisini ve önceki kategorizasyon denemesini de bu düğümün çıktısına ekliyoruz.
      // Bu sayede LLM zincirinden sonra bu veriye eksiksiz erişebileceğiz.
      original_lead_data: leadWithCategorizationAttempt,

      // LLM'in ihtiyaç duyduğu veri
      llm_messages: messagesForLlm
    }
  });
}

return results;

// --- Varsayılan Hata Çıktısı ---
const defaultErrorLlmOutput = {
  original_german_category: "Unknown (LLM Error)",
  refined_english_general_poi: "Error/Unknown",
  mapped_poi_category_german: "Fehler/Unbekannt",
  mapped_poi_category_turkish: "Hata/Bilinmiyor"
};

// --- ANA İŞLEM MANTIĞI ---
const items = $input.all();
const results = [];

for (const item of items) {
  // Bu düğüme gelen veride artık hem 'text' (LLM çıktısı) hem de 'original_lead_data' var.
  const inputData = item.json;

  // 1. Orijinal lead verisini ve LLM metnini ayıralım
  const originalLeadData = $("Code (Prepare LLM Prompt - Placeholder)").first().json.original_lead_data;
  const raw_llm_response_text = inputData.text || null;

  let llm_processed_output;
  let llm_parsing_error_message = null;

  // Hata durumunda kullanılacak orijinal kategori adını al
  const originalGermanCategorySentToLlm = originalLeadData.categorization_attempt.original_german_category_for_processing;

  // 2. LLM YANITINI AYRIŞTIRMA (Parse)
  if (raw_llm_response_text) {
    try {
      // ```json bloğunu ve olası baştaki/sondaki boşlukları temizle
      const jsonRegex = /```json\s*([\s\S]*?)\s*```/;
      const match = raw_llm_response_text.match(jsonRegex);
      const jsonContentToParse = match ? match[1].trim() : raw_llm_response_text.trim();

      llm_processed_output = JSON.parse(jsonContentToParse);

      // Beklenen alanların varlığını kontrol et
      if (!llm_processed_output.refined_english_general_poi || !llm_processed_output.mapped_poi_category_german) {
        throw new Error("LLM yanıtı beklenen 'refined_english_general_poi' veya 'mapped_poi_category_german' alanlarını içermiyor.");
      }
    } catch (e) {
      llm_parsing_error_message = `LLM JSON yanıtı ayrıştırılamadı: ${e.message}. Ham yanıt: ${raw_llm_response_text}`;
      llm_processed_output = {
        ...defaultErrorLlmOutput,
        original_german_category: originalGermanCategorySentToLlm
      };
    }
  } else {
    llm_parsing_error_message = "LLM'den metin yanıtı alınamadı (input.text boş veya tanımsız).";
    llm_processed_output = {
      ...defaultErrorLlmOutput,
      original_german_category: originalGermanCategorySentToLlm
    };
  }

  // 3. NİHAİ ÇIKTIYI OLUŞTUR
  // Hem orijinal lead verisini hem de LLM'in işlenmiş sonucunu birleştir.
  // Bu yapı, bir sonraki Merge düğümüne her iki koldan da tutarlı veri gelmesini sağlar.
  results.push({
    json: {
      ...originalLeadData, // id, name, cid, categorization_attempt vb. her şey burada
      llm_result: { // LLM'den gelen tüm bilgileri bu nesne altına topla
        categorization_engine_used: 'llm',
        processed_output: llm_processed_output,
        parsing_error: llm_parsing_error_message,
        raw_response: raw_llm_response_text
      }
    }
  });
}

return results;

// --- SABİT HARİTALAR VE VARSAYILAN DEĞERLER ---

const yaskaSectorMapping = {
  "Sağlık Sektörü": { english_keywords_general_poi: ["Health & Medical"], yaska_category_group_tr: "Sağlık Sektörü", yaska_category_group_en: "Healthcare Sector", yaska_category_group_de: "Gesundheitssektor" },
  "Otomotiv Sektörü": { english_keywords_general_poi: ["Automotive", "Automotive / Shopping", "Transportation"], yaska_category_group_tr: "Otomotiv Sektörü", yaska_category_group_en: "Automotive Sector", yaska_category_group_de: "Automobilsektor" },
  "Hukuk Sektörü": { english_keywords_general_poi: ["Professional Services", "Legal"], yaska_category_group_tr: "Hukuk Sektörü", yaska_category_group_en: "Legal Sector", yaska_category_group_de: "Rechtssektor" },
  "Zanaatkar/Usta Sektörü": { english_keywords_general_poi: ["Construction & Home Improvement", "Services", "Craftsmanship", "Trades"], yaska_category_group_tr: "Zanaatkar/Usta Sektörü", yaska_category_group_en: "Craftsmen/Trades Sector", yaska_category_group_de: "Handwerkssektor" },
  "Emlak Sektörü": { english_keywords_general_poi: ["Real Estate", "Property"], yaska_category_group_tr: "Emlak Sektörü", yaska_category_group_en: "Real Estate Sector", yaska_category_group_de: "Immobiliensektor" },
  "Güzellik Sektörü": { english_keywords_general_poi: ["Personal Care & Beauty", "Health & Wellness", "Salon"], yaska_category_group_tr: "Güzellik Sektörü", yaska_category_group_en: "Beauty Sector", yaska_category_group_de: "Schönheitssektor" },
  "Eğitim Sektörü": { english_keywords_general_poi: ["Education", "Education & Culture"], yaska_category_group_tr: "Eğitim Sektörü", yaska_category_group_en: "Education Sector", yaska_category_group_de: "Bildungssektor" },
  "Genel Hizmet Sektörü": { english_keywords_general_poi: ["Food & Drink", "Accommodation", "Services (General)", "Arts & Entertainment", "Tourism", "Shopping", "Retail", "Business Services", "Financial Services", "Professional Services", "Legal"], yaska_category_group_tr: "Genel Hizmet Sektörü", yaska_category_group_en: "General Services Sector", yaska_category_group_de: "Allgemeiner Dienstleistungssektor" },
  "Diğer/Bilinmeyen": { english_keywords_general_poi: [], yaska_category_group_tr: "Diğer/Bilinmeyen", yaska_category_group_en: "Other/Unknown", yaska_category_group_de: "Sonstige/Unbekannt" }
};

const defaultYaskaSector = {
  ...yaskaSectorMapping["Diğer/Bilinmeyen"],
  match_type: "ultimate_fallback"
};

const defaultGeneralPoi = {
  mapped_poi_category_english: "Uncategorized",
  mapped_poi_category_german: "Unkategorisiert",
  mapped_poi_category_turkish: "Kategorize Edilmemiş",
  source: 'ultimate_fallback'
};


// --- ANA İŞLEM MANTIĞI ---

const items = $input.all();
const results = [];

for (const item of items) {
  const leadData = item.json;

  let final_general_poi = null;
  let final_yaska_sector = null;
  let source_of_truth = 'kural_tabanli'; // Varsayılan kaynak

  // Adım 1: En güvenilir POI bilgisini seç (Öncelik: LLM)
  if (leadData.llm_result && leadData.llm_result.processed_output && leadData.llm_result.processed_output.refined_english_general_poi !== "Error/Unknown") {
    // LLM sonucu geçerliyse, onu kullan
    const llmOutput = leadData.llm_result.processed_output;
    final_general_poi = {
      original_german_category: llmOutput.original_german_category,
      mapped_poi_category_english: llmOutput.refined_english_general_poi,
      mapped_poi_category_german: llmOutput.mapped_poi_category_german,
      mapped_poi_category_turkish: llmOutput.mapped_poi_category_turkish,
      source: 'llm_valid'
    };
    source_of_truth = 'llm';
  } else if (leadData.categorization_attempt && leadData.categorization_attempt.general_poi_info_from_db) {
    // LLM yoksa veya geçersizse, kural tabanlı sonucu kullan
    final_general_poi = {
      ...leadData.categorization_attempt.general_poi_info_from_db,
      source: 'rule_based_valid'
    };
  } else {
    // Hiçbir geçerli sonuç yoksa, varsayılanı kullan
    final_general_poi = {
      ...defaultGeneralPoi,
      original_german_category: leadData.categorization_attempt?.original_german_category_for_processing || leadData.category || "N/A",
    };
  }

  // Adım 2: Nihai Yaska Sektörünü Belirle
  // Öncelik sırası: LLM'in bulduğu POI'den türetilen sektör > Kural tabanlı bulunan sektör > Varsayılan
  let found_yaska = false;
  if (final_general_poi.mapped_poi_category_english) {
    for (const sectorName in yaskaSectorMapping) {
      const sectorData = yaskaSectorMapping[sectorName];
      if (sectorData.english_keywords_general_poi.includes(final_general_poi.mapped_poi_category_english)) {
        final_yaska_sector = {
          yaska_tr: sectorData.yaska_category_group_tr,
          yaska_en: sectorData.yaska_category_group_en,
          yaska_de: sectorData.yaska_category_group_de,
          match_type: `yaska_from_${source_of_truth}`
        };
        found_yaska = true;
        break;
      }
    }
  }

  // Eğer POI bilgisiyle bir sektör bulunamadıysa, kural tabanlı ilk denemedeki sonucu kullanmayı dene
  if (!found_yaska && leadData.categorization_attempt?.yaska_sector_info && leadData.categorization_attempt.yaska_sector_info.match_type !== "fallback_needs_llm") {
      final_yaska_sector = leadData.categorization_attempt.yaska_sector_info;
  } 
  // Hala bulunamadıysa, varsayılanı ata
  else if (!found_yaska) {
      final_yaska_sector = { ...defaultYaskaSector };
  }

  // Adım 3: Tüm verileri standart bir formatta birleştir
  const outputJson = {
    // Orijinal lead'den gelen tüm ana alanları koru
    ...leadData, 

    // Kategorizasyonla ilgili tüm nihai bilgileri bu nesneye topla
    final_categorization: {
      yaska_sector: final_yaska_sector,
      general_poi: final_general_poi
    },

    // Veritabanı ve sonraki adımlarda kolay erişim için ana alanları en üste çıkar
    // Bu, Expressions'larda `{{ $json.yaska_sector_tr }}` gibi kolay kullanım sağlar
    original_german_category: final_general_poi.original_german_category,
    category_group_en: final_general_poi.mapped_poi_category_english,
    category_group_de: final_general_poi.mapped_poi_category_german,
    category_group_tr: final_general_poi.mapped_poi_category_turkish,
    yaska_sector_tr: final_yaska_sector.yaska_tr,
    yaska_sector_de: final_yaska_sector.yaska_de,
    yaska_sector_en: final_yaska_sector.yaska_en
  };

  // Artık ihtiyaç duyulmayan ara işlem nesnelerini temizle (Opsiyonel ama önerilir)
  delete outputJson.categorization_attempt;
  delete outputJson.llm_result;

  results.push({ json: outputJson });
}

return results;

const lead = $("Set (Current Lead Data)").first().json; // From 'Set (Current Lead Data)'
